export const interestMaximiserEngineSource = "// Interest Maximiser domain logic shared by the Launchpad browser demo and the\n// downloaded interest-maximiser.mjs. All money is integer minor units (cents).\nimport { decimalToMinor } from './sample-helpers.mjs';\n\nexport function pendingDebitsMinor(transactions) {\n  return transactions\n    .filter(row => row.status === 'PENDING' && row.type === 'DEBIT')\n    .reduce((sum, row) => sum + Math.abs(decimalToMinor(row.amount)), 0);\n}\n\nexport function transferPreviewMinor({ balanceMinor, pendingMinor, reserveMinor, targetBalanceMinor = 0 }) {\n  const transferableMinor = Math.max(0, balanceMinor - pendingMinor - reserveMinor);\n  return {\n    transferableMinor,\n    sourceAfterMinor: balanceMinor - transferableMinor,\n    targetAfterMinor: targetBalanceMinor + transferableMinor,\n  };\n}\n";
export const spendExplorerEngineSource = "// Spend Explorer engine (Launchpad illustrative example kit). Fictional data only; no network or credentials.\n// Reads the documented data.transactions envelope; totals use exact integer minor units.\nimport { decimalToMinor } from './sample-helpers.mjs';\n\nexport function categorise(description) {\n  const value = description.toLowerCase();\n  if (/woolies|checkers|pick n pay/.test(value)) return 'Groceries';\n  if (/gautrain|bolt|uber/.test(value)) return 'Transport';\n  if (/coffee|kauai|nandos/.test(value)) return 'Eating out';\n  if (/city power/.test(value)) return 'Utilities';\n  if (/showmax|spotify/.test(value)) return 'Subscriptions';\n  if (/engen|sasol/.test(value)) return 'Fuel';\n  return 'Other';\n}\n\nexport function spendRows(transactions) {\n  return transactions.map((row, index) => ({\n    id: row.uuid || `transaction-${index}`,\n    date: row.postingDate || row.transactionDate || row.valueDate,\n    description: row.description,\n    category: categorise(row.description),\n    amountMinor: Math.abs(decimalToMinor(row.amount)),\n    status: row.status,\n    type: row.type,\n  }));\n}\n\nexport function filterSpendRows(rows, { category = 'all', search = '' } = {}) {\n  const wanted = category.toLowerCase();\n  const text = search.toLowerCase();\n  return rows.filter(row => (wanted === 'all' || row.category.toLowerCase() === wanted)\n    && (!text || row.description.toLowerCase().includes(text)));\n}\n\n// Posted debits only; pending rows can change or disappear before posting. Largest total first.\nexport function postedDebitTotalsMinor(rows) {\n  const totals = new Map();\n  for (const row of rows) {\n    if (row.status !== 'POSTED' || row.type !== 'DEBIT') continue;\n    totals.set(row.category, (totals.get(row.category) ?? 0) + row.amountMinor);\n  }\n  return [...totals].sort((a, b) => b[1] - a[1]);\n}\n";
export const cardGuardEngineSource = "// Card Guard rules engine (Launchpad illustrative example kit). Fictional data only; no card or bank connection.\n// Amounts use the en-ZA convention: \"R 1 500,00\", grouped with a no-break space (U+00A0) and a decimal comma.\n// The formatter is explicit so output does not depend on the host's locale data.\nconst GROUP_SEPARATOR = '\\u00a0';\n\nexport function formatRand(amount) {\n  if (typeof amount !== 'number' || !Number.isFinite(amount)) return 'R ' + String(amount);\n  const [whole, cents] = Math.abs(amount).toFixed(2).split('.');\n  const sign = amount < 0 && Number(whole + cents) !== 0 ? '-' : '';\n  return 'R ' + sign + whole.replace(/\\B(?=(\\d{3})+(?!\\d))/g, GROUP_SEPARATOR) + ',' + cents;\n}\n\nexport function decide(purchase, rules) {\n  if (!Number.isFinite(purchase.amount) || purchase.amount <= 0) {\n    return { approved: false, reason: 'Invalid amount' };\n  }\n  const blocked = rules.blockedCategories.map(category => category.toLowerCase());\n  if (blocked.includes(purchase.merchantCategory.toLowerCase())) {\n    return { approved: false, reason: 'Merchant category ' + purchase.merchantCategory + ' is restricted' };\n  }\n  if (purchase.amount > rules.spendLimit) {\n    return { approved: false, reason: 'Amount exceeds limit of ' + formatRand(rules.spendLimit) };\n  }\n  return { approved: true, reason: 'Within limit and merchant allowed' };\n}\n";
export const paymentPingerEngineSource = "// Payment Pinger domain logic shared by the Launchpad browser demo and the downloaded\n// starter script (embedded via scripts/generate-engine-sources.mjs). Pure: no I/O, no imports.\nexport function validatePingerTxn(t) {\n  const errors = [];\n  if (!t || typeof t !== 'object') return ['transaction must be an object'];\n  if (typeof t.merchant !== 'string' || t.merchant.trim() === '') errors.push('merchant is required');\n  else if (t.merchant.length > 80) errors.push('merchant must be 80 characters or fewer');\n  if (typeof t.amount !== 'number' || !Number.isFinite(t.amount)) errors.push('amount must be a number');\n  else if (t.amount <= 0) errors.push('amount must be greater than 0');\n  if (typeof t.currency !== 'string' || !/^[A-Z]{3}$/.test(t.currency)) errors.push('currency must be a 3-letter uppercase code like ZAR');\n  if (t.city !== undefined && typeof t.city !== 'string') errors.push('city must be text');\n  if (t.cardLast4 !== undefined && t.cardLast4 !== '' && !/^\\d{4}$/.test(String(t.cardLast4))) errors.push('cardLast4 must be exactly 4 digits');\n  return errors;\n}\n\nexport function previewPing(t) {\n  const errors = validatePingerTxn(t);\n  if (errors.length) return { ok: false, errors: errors, message: null, alert: null, foreign: false };\n  const amt = t.currency + ' ' + t.amount.toFixed(2);\n  const city = typeof t.city === 'string' ? t.city.trim() : '';\n  const where = t.merchant.trim() + (city ? ' (' + city + ')' : '');\n  const card = t.cardLast4 ? ' - card ending ' + t.cardLast4 : '';\n  const message = 'Card payment: ' + amt + ' at ' + where + card;\n  const foreign = t.currency !== 'ZAR';\n  const alert = foreign ? 'Non-ZAR alert: ' + amt + ' at ' + where + '. Check that this was you.' : null;\n  return { ok: true, errors: [], message: message, alert: alert, foreign: foreign };\n}\n";
export const cardToSheetSyncEngineSource = "// Card-To-Sheet-Sync domain logic shared by the Launchpad browser demo and the downloaded\n// starter script (embedded via scripts/generate-engine-sources.mjs). Pure: no I/O, no imports.\nexport function validateSheetTxn(t) {\n  const errors = [];\n  if (!t || typeof t !== 'object') return ['transaction must be an object'];\n  if (typeof t.date !== 'string' || !/^\\d{4}-\\d{2}-\\d{2}$/.test(t.date) || Number.isNaN(Date.parse(t.date + 'T00:00:00Z')) || new Date(t.date + 'T00:00:00Z').toISOString().slice(0, 10) !== t.date) errors.push('date must be YYYY-MM-DD');\n  if (typeof t.merchant !== 'string' || t.merchant.trim() === '') errors.push('merchant is required');\n  if (typeof t.amount !== 'number' || !Number.isFinite(t.amount)) errors.push('amount must be a number');\n  else if (t.amount <= 0) errors.push('amount must be greater than 0');\n  if (typeof t.currency !== 'string' || !/^[A-Z]{3}$/.test(t.currency)) errors.push('currency must be a 3-letter uppercase code');\n  if (t.status !== 'approved' && t.status !== 'declined') errors.push('status must be approved or declined');\n  if (t.category !== undefined && typeof t.category !== 'string') errors.push('category must be text');\n  return errors;\n}\n\nexport function buildSheetRows(txns) {\n  if (!Array.isArray(txns)) throw new Error('transactions must be an array');\n  const rows = [];\n  const skipped = [];\n  txns.forEach(function (t, i) {\n    const errors = validateSheetTxn(t);\n    if (errors.length) { skipped.push({ index: i, reason: errors.join('; ') }); return; }\n    if (t.status !== 'approved') { skipped.push({ index: i, reason: 'status is ' + t.status + '; only approved rows are written' }); return; }\n    rows.push({ date: t.date, merchant: t.merchant.trim(), category: t.category || '', amount: t.amount, currency: t.currency });\n  });\n  return { rows: rows, skipped: skipped };\n}\n\nexport function csvCell(v) {\n  if (typeof v === 'number') return Number.isFinite(v) ? v.toFixed(2) : '';\n  let s = v === null || v === undefined ? '' : String(v);\n  // Neutralise spreadsheet formulas (CSV injection): =, +, -, @, |, % and leading tab/CR.\n  if (/^\\s*[=+\\-@|%]/.test(s) || /^[\\t\\r]/.test(s)) s = \"'\" + s;\n  if (/[\",\\r\\n]/.test(s) || /^\\s|\\s$/.test(s)) s = '\"' + s.replace(/\"/g, '\"\"') + '\"';\n  return s;\n}\n\nexport function rowsToCsv(rows) {\n  const header = ['Date', 'Merchant', 'Category', 'Amount', 'Currency'];\n  const lines = [header.map(csvCell).join(',')];\n  rows.forEach(function (r) { lines.push([r.date, r.merchant, r.category, r.amount, r.currency].map(csvCell).join(',')); });\n  return lines.join('\\r\\n') + '\\r\\n';\n}\n";
export const swipeNSaveEngineSource = "// Swipe n Save domain logic shared by the Launchpad browser demo and the downloaded\n// starter script (embedded via scripts/generate-engine-sources.mjs). Pure: no I/O, no imports.\nexport function validatePercent(p) {\n  if (typeof p !== 'number' || !Number.isFinite(p)) return 'percent must be a number';\n  if (p < 1 || p > 10000) return 'percent must be between 1 and 10000';\n  return null;\n}\n\nexport function swipeSaving(t, pct) {\n  const errors = [];\n  if (!t || typeof t !== 'object') return { ok: false, errors: ['transaction must be an object'], saving: 0, excluded: false, reason: '' };\n  if (typeof t.merchant !== 'string' || t.merchant.trim() === '') errors.push('merchant is required');\n  if (typeof t.amount !== 'number' || !Number.isFinite(t.amount)) errors.push('amount must be a number');\n  else if (t.amount <= 0) errors.push('amount must be greater than 0');\n  if (typeof t.mcc !== 'string' || !/^\\d{4}$/.test(t.mcc)) errors.push('mcc must be a 4-digit merchant category code');\n  if (errors.length) return { ok: false, errors: errors, saving: 0, excluded: false, reason: errors.join('; ') };\n  if (t.mcc === '6011') return { ok: true, errors: [], saving: 0, excluded: true, reason: 'ATM withdrawal (MCC 6011) excluded' };\n  const saving = Math.round(t.amount * pct) / 100;\n  return { ok: true, errors: [], saving: saving, excluded: false, reason: pct + '% of ' + t.amount.toFixed(2) };\n}\n\nexport function simulateSwipe(txns, pct) {\n  const pe = validatePercent(pct);\n  if (pe) return { ok: false, error: pe, results: [], total: 0 };\n  if (!Array.isArray(txns)) return { ok: false, error: 'transactions must be an array', results: [], total: 0 };\n  const results = txns.map(function (t) { return { txn: t, result: swipeSaving(t, pct) }; });\n  const cents = results.reduce(function (a, r) { return a + Math.round(r.result.saving * 100); }, 0);\n  return { ok: true, error: null, results: results, total: cents / 100 };\n}\n";
